import type { Metadata } from "next";

/**
 * Generated by src/app/opengraph-image.tsx. Pages that define their own `openGraph` object replace the
 * root file-based image, so each one references this explicitly (audit F-10).
 */
export const ogImage = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  type: "image/png",
  alt: "Brian Ramoroka, web developer in Cape Town",
};

/** Title, description, canonical, Open Graph and Twitter from one call, so they never drift apart. */
export function pageMetadata({ title, description, path }: { title: string; description: string; path: string }): Metadata {
  return {
    title,
    description,
    alternates: { canonical: path },
    openGraph: { title, description, url: path, type: "website", locale: "en_ZA", siteName: "Brian Ramoroka", images: [ogImage] },
    twitter: { card: "summary_large_image", title, description, images: [ogImage.url] },
  };
}
